import os, shutil, subprocess, sys, tempfile
R = os.getcwd()
mod = os.path.join(tempfile.mkdtemp(), 'mod')
shutil.copytree(R + '/.claude/skills/kbmon-pane', mod)
TEST = r"""import { expect, mock, test } from 'claude-code/testing'

test('a notification is told once for each entry that appears, goes or changes its kind', async ($, on) => {
  const clock = mock.clock(on)
  let needs = 'nothing'
  const notified: string[] = []
  const run = (stdout: string) => ({ value: { exitCode: 0, stdout, stderr: '' } })
  on('process.run', ($, e) => {
    const argv = e.argv as string[]
    if (argv.includes('--receipt')) {
      return run(JSON.stringify({ line: 'kbmon: no alert on querylog; needs you: 1', fingerprint: 'f1' }))
    }
    if (argv.includes('--status')) {
      return run(`needs you: ${needs}\nsessions: none\n`)
    }
    return run(`kbmon · 2026-10-24 10:00\nneeds you: ${needs}\n\nkb: 1 root\n`)
  })
  on('ui.notify', ($, e) => {
    notified.push(e.text)

    return { value: { isSent: true, channel: 'terminal_bell' } }
  })
  on('ui.toast', () => ({ value: undefined }))
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('command.register', () => ({ value: undefined }))
  on('session.start', () => ({ cwd: '/work' }))

  const step = async (line: string, told: number) => {
    needs = line
    await clock.advance(60000)
    await clock.settle()
    expect(notified.length).toBe(told)
  }

  await $.session.start({ surface: 'terminal', isInteractive: true, cwd: '/work' })
  await clock.advance(2000)
  await clock.settle()
  expect(notified.length).toBe(0)

  // an entry appears
  await step('SP-aaaaaaaa gate start', 1)
  // the same line again, and a line that lost nothing but gained a not-read suffix
  await step('SP-aaaaaaaa gate start', 1)
  await step('SP-aaaaaaaa gate start; not read: host', 1)
  // a second entry appears, then only its age moves
  await step('SP-aaaaaaaa gate start; ST-bbbbbbbb blocked on gate g1, 5m', 2)
  await step('SP-aaaaaaaa gate start; ST-bbbbbbbb blocked on gate g1, 6m', 2)
  await step('SP-aaaaaaaa gate start; ST-bbbbbbbb blocked on gate g1, 1h05m', 2)
  // a panel that was not read hides the entries, and their return is no news
  await step('nothing; not read: sprint', 2)
  await step('SP-aaaaaaaa gate start; ST-bbbbbbbb blocked on gate g1, 1h06m', 2)
  // the same item changes its kind
  await step('SP-aaaaaaaa gate start; ST-bbbbbbbb run failed at step rebase, 7m', 3)
  // an orphan and an overlap appear, their ages move
  await step('SP-aaaaaaaa gate start; ST-bbbbbbbb run failed at step rebase, 8m; orphan pid 42 (5m, in /work)', 4)
  await step('SP-aaaaaaaa gate start; ST-bbbbbbbb run failed at step rebase, 9m; orphan pid 42 (6m, in /work)', 4)
  await step('SP-aaaaaaaa gate start; overlap ST-aaaaaaaa (s-1) with ST-bbbbbbbb (s-2), undecided for 12m; orphan pid 42 (7m, in /work)', 5)
  await step('SP-aaaaaaaa gate start; overlap ST-aaaaaaaa (s-1) with ST-bbbbbbbb (s-2), undecided for 13m; orphan pid 42 (8m, in /work)', 5)
  // an entry goes while others stay
  await step('SP-aaaaaaaa gate start; orphan pid 42 (9m, in /work)', 6)
  // the last entry goes: nothing is told
  await step('nothing', 6)
})
"""
open(os.path.join(mod, 'planted.test.ts'), 'w', encoding='utf-8').write(TEST)
def claude(*args):
    for d in os.environ.get('PATH', '').split(os.pathsep):
        p = os.path.join(d, 'claude')
        if os.path.isfile(p) and os.access(p, os.X_OK):
            r = subprocess.run([p, *args], capture_output=True, text=True, timeout=240)
            if 'not run from this spelling' not in r.stdout + r.stderr:
                return r
    print('no claude binary that runs plugin test')
    sys.exit(1)
r = claude('plugin', 'test', mod)
print((r.stdout + r.stderr)[-1500:])
sys.exit(1 if r.returncode != 0 else 0)
